      "trigger_condition": "readAccessToken() resolves to a non-null but empty string",
      "guard_snippet": "if (userToken != null && userToken.isNotEmpty) { options.headers['Authorization'] = 'Bearer $userToken'; }",
      "potential_consequence": "backend receives a syntactically-present but empty bearer token instead of the request being treated as unauthenticated"
    },
    {
      "location": "lib/core/network/retry_interceptor.dart:74-77",
      "trigger_condition": "NETWORK_TIMEOUT/NETWORK_OFFLINE/RATE_LIMITED (etc.) occurs on auth-signup or auth-login",
      "guard_snippet": "add a neverRetriedFunctions check (by HeaderInterceptor.functionNameOf) excluding auth-signup/auth-login from shouldRetry",
      "potential_consequence": "the non-idempotent signup/login POST is transparently resent, risking a duplicate account-creation/login attempt"
    },
    {
      "location": "lib/core/navigation/app_router.dart:97-114",
      "trigger_condition": "user is on /reauth when SessionStatus transitions from expired back to authenticated",
      "guard_snippet": "if (location == AppRoutePaths.reauth && status == SessionStatus.authenticated) return AppRoutePaths.home;",
      "potential_consequence": "user is stranded on the throwaway biometric-reauth placeholder despite being fully authenticated again"
