      "location": "lib/core/navigation/expiry_overlay_host.dart:99-104",
      "trigger_condition": "statusStream emits expired before the root Navigator's overlay context is mounted",
      "guard_snippet": "on overlayContext == null, reschedule another addPostFrameCallback instead of just resetting _expiryOverlayShown",
      "potential_consequence": "the session-expiry recovery overlay never appears for that expiry episode since the status never re-fires"
    },
    {
      "location": "lib/features/auth/presentation/cubit/auth_cubit.dart:32-63",
      "trigger_condition": "user edits email/password or taps the mode-toggle link while state.isSubmitting is true",
      "guard_snippet": "if (state.isSubmitting) return; at the top of toggleMode/emailChanged/passwordChanged",
      "potential_consequence": "the in-flight submit's result (success/error, password-clear) is applied on top of state the user already mutated, showing mismatched mode/email/password"
    },
    {
      "location": "lib/features/auth/data/repositories/auth_repository_impl.dart:57-64",
      "trigger_condition": "auth-signup/auth-login response returns an empty-string accessToken or refreshToken",
      "guard_snippet": "validate accessToken/refreshToken are non-empty before saveSession, else return left(Failure.malformedResponse(...))",
      "potential_consequence": "an empty token is persisted and later sent as an empty Bearer header on every subsequent request"
